(function(g){'use strict';const G=g.GridKit=g.GridKit||{};
G.escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
G.clamp=(n,a=0,b=1)=>Math.min(b,Math.max(a,Number(n)||0));
G.uid=(()=>{let i=0;return()=>`grid-${++i}`})();
G.icons={arrow:'M5 12H19M13 6L19 12L13 18',copy:'M9 8V4H20V16H16M4 8H16V20H4Z',check:'M5 12L10 17L20 6',close:'M6 6L18 18M18 6L6 18',crown:'M3 7L8 11L12 4L16 11L21 7L19 19H5Z',wifi:'M3 8Q12 1 21 8M6 12Q12 7 18 12M9 16Q12 13 15 16M12 20H12.1',sound:'M3 9H7L12 5V19L7 15H3ZM16 8Q21 12 16 16',mute:'M3 9H7L12 5V19L7 15H3ZM16 9L22 15M22 9L16 15',flag:'M5 22V3M5 3Q10 0 15 4Q19 7 22 3V14Q18 17 14 13Q10 10 5 13',clock:'M12 5V12L17 15M22 12A10 10 0 1 1 2 12A10 10 0 1 1 22 12',gear:'M9 3H15L16 7L20 8L22 13L18 16L17 21H11L9 17L5 16L3 11L7 8ZM15 12A3 3 0 1 1 9 12A3 3 0 1 1 15 12',keyboard:'M2 5H22V19H2ZM5 9H6M10 9H11M15 9H16M19 9H20M5 13H6M10 13H11M15 13H16M6 16H18',bolt:'M14 2L4 14H11L9 22L21 9H13Z',user:'M16 7A4 4 0 1 1 8 7A4 4 0 1 1 16 7M4 22V19Q4 13 12 13Q20 13 20 19V22',refresh:'M20 8A9 9 0 1 0 21 16M20 2V8H14',alert:'M12 2L23 21H1ZM12 8V14M12 18H12.1',minus:'M5 12H19',plus:'M5 12H19M12 5V19',link:'M9 15L15 9M8 16L6 18Q2 21 1 16Q0 13 3 10L7 6Q11 3 14 6M10 18Q13 21 17 17L21 13Q24 9 21 6Q18 3 15 6'};
G.icon=(name,size=20)=>`<svg xmlns="http://www.w3.org/2000/svg" width="${G.clamp(size,12,64)}" height="${G.clamp(size,12,64)}" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="${G.icons[name]||G.icons.bolt}"/></svg>`;
G.button=(text,{variant='primary',icon,disabled=false,loading=false,attrs=''}={})=>`<button type="button" class="g-btn g-btn--${['primary','secondary','danger','ghost'].includes(variant)?variant:'primary'}" ${disabled||loading?'disabled':''} ${loading?'aria-busy="true"':''} ${attrs}>${loading?'<span class="g-spinner" aria-hidden="true"></span>':icon?G.icon(icon):''}${G.escape(text)}</button>`;
G.banner=(text,tone='info')=>`<div class="g-banner g-banner--${['info','error','success','warning'].includes(tone)?tone:'info'}">${G.icon(tone==='error'?'alert':tone==='success'?'check':'wifi')}<span>${G.escape(text)}</span></div>`;
G.toast=(message,tone='info')=>{let region=document.querySelector('.g-toasts');if(!region){region=document.createElement('div');region.className='g-toasts';region.setAttribute('role','status');region.setAttribute('aria-live','polite');document.body.append(region)}const item=document.createElement('div');item.innerHTML=G.banner(message,tone);region.append(item);setTimeout(()=>item.remove(),4000)};
G.copy=async text=>{try{await navigator.clipboard.writeText(text);G.toast('Copied to clipboard.','success');return true}catch{G.toast('Copy unavailable. Select and copy the visible value.','warning');return false}};
G.tooltip=(label,explanation)=>{const id=G.uid();return `<span class="g-tip-wrap"><button type="button" class="g-tip-target" aria-describedby="${id}">${G.escape(label)} ${G.icon('alert',14)}</button><span id="${id}" class="g-tooltip" role="tooltip">${G.escape(explanation)}</span></span>`};
G.escapeTooltip=event=>{if(event.key==='Escape')document.querySelectorAll('.g-tip-wrap').forEach(w=>w.classList.add('dismissed'))};
G.skeleton=()=>'<div class="g-skeleton" role="status" aria-label="Loading"><span></span><span></span><span></span></div>';
G.emptySeat=n=>`<div class="g-empty-seat">${G.icon('plus')}<span>Seat ${n}<small>Waiting for a racer</small></span></div>`;
})(globalThis);
